                </div>
                <button type="button" class="inline-flex items-center gap-1 type-ui text-ink-muted hover:text-ink" @click="setSampleGuideState('hidden')"><X class="workspace-icon-sm" aria-hidden="true" /><span>Hide sample guide</span></button>
              </div>
              <p class="mt-stack-sm max-w-4xl type-body text-ink-secondary">Open Daniel Reed — Sample for a complete worked client with aims, Therapy Focus, transcript, reviewed Session Capture and summary. Or use Transcript Inbox to assign an unassigned Alex Morgan — Sample import, then explore Alex’s longitudinal history.</p>
              <p class="mt-stack-xs type-metadata text-ink-muted">Sample AI demonstrations are deterministic and do not use your monthly AI allowance. Sample clients can be archived separately when you no longer need them.</p>
              <div class="mt-stack-md flex flex-wrap items-center gap-inline-sm">
                <AppButton variant="primary" @click="openSampleDaniel"><UserRound class="workspace-icon" aria-hidden="true" /><span>Open Daniel worked example</span></AppButton>
                <AppButton variant="secondary" @click="openSampleInbox"><Inbox class="workspace-icon" aria-hidden="true" /><span>Practise transcript triage</span></AppButton>
                <button type="button" class="inline-flex min-h-touch items-center gap-1 px-inline-sm type-ui text-ink-muted hover:text-ink" @click="setSampleGuideState('collapsed')"><ChevronUp class="workspace-icon-sm" aria-hidden="true" /><span>Collapse</span></button>
              </div>
            </div>
          </div>
        </div>
        <div v-else class="flex flex-wrap items-center justify-between gap-inline-md px-inline-md py-stack-sm">
          <div class="flex min-w-0 items-center gap-inline-sm">
            <Sparkles class="workspace-icon text-accent" aria-hidden="true" />
            <div class="min-w-0"><span class="type-ui font-semibold text-ink">Sample practice</span><span class="ml-2 type-metadata text-ink-muted">Daniel worked example · Alex transcript triage</span></div>
          </div>
          <div class="flex items-center gap-inline-sm">
            <button type="button" class="inline-flex min-h-touch items-center gap-1 px-inline-sm type-ui text-accent hover:text-ink" @click="setSampleGuideState('expanded')"><ChevronDown class="workspace-icon-sm" aria-hidden="true" /><span>Open guide</span></button>
            <button type="button" class="inline-flex min-h-touch items-center gap-1 px-inline-sm type-ui text-ink-muted hover:text-ink" @click="setSampleGuideState('hidden')"><X class="workspace-icon-sm" aria-hidden="true" /><span>Hide</span></button>
          </div>
        </div>
      </div>
      <div v-if="sampleActionError" role="alert" class="mb-stack-md rounded-control border border-state-danger/20 bg-state-danger/5 px-inline-md py-stack-sm type-body text-state-danger">{{ sampleActionError }}</div>
      <div class="grid grid-cols-1 md:grid-cols-5 gap-inline-md md:items-center mb-stack-md"><FormControl class="md:col-span-3"><template #default="{controlClass}"><span class="sr-only">Search clients</span><div class="relative"><Search class="pointer-events-none absolute left-3 top-1/2 workspace-icon -translate-y-1/2 text-accent" aria-hidden="true" /><input v-model="searchQuery" type="search" placeholder="Search clients by name or reference…" :class="[controlClass,'pl-10 placeholder:text-ink-muted']" data-testid="client-search" /></div></template></FormControl><div class="md:col-span-2 inline-flex min-h-touch self-start rounded-control border border-border bg-surface p-1" role="group" aria-label="Client status filter"><button v-for="option in statusOptions" :key="option.value" type="button" class="flex-1 min-h-touch px-inline-md rounded-control type-ui transition-colors" :aria-pressed="statusFilter===option.value" :class="statusFilter===option.value?'bg-state-selected text-ink font-semibold':'text-ink-secondary hover:bg-surface-subtle'" @click="statusFilter=option.value">{{ option.label }} <span class="text-ink-muted">{{ option.count }}</span></button></div></div>
      <div class="flex items-center justify-between gap-inline-md mb-stack-sm"><p class="type-metadata text-ink-muted">{{ resultLabel }}</p><button v-if="samplePracticeReady && sampleGuideState==='hidden'" type="button" class="type-metadata text-accent hover:text-ink" @click="setSampleGuideState('collapsed')">Show sample guide</button></div>
      <div v-if="filteredClients.length===0" class="bg-surface-elevated border border-border-muted p-inline-lg py-stack-xl rounded-panel text-center"><p class="type-body text-ink-secondary">{{ searchQuery?'No clients match your search.':emptyStatusMessage }}</p></div>
      <div v-else class="bg-surface-elevated border border-border-muted rounded-panel overflow-hidden"><table class="w-full text-left border-collapse"><thead class="bg-surface-subtle border-b border-border-muted"><tr><th class="px-inline-lg py-stack-md type-eyebrow text-ink-secondary">Client</th><th class="px-inline-lg py-stack-md type-eyebrow text-ink-secondary">Next appointment</th><th v-if="statusFilter==='all'" class="px-inline-lg py-stack-md type-eyebrow text-ink-secondary">Status</th><th class="px-inline-lg py-stack-md type-eyebrow text-ink-secondary text-right"><span class="sr-only">Client actions</span></th></tr></thead><tbody class="divide-y divide-border-muted"><tr v-for="client in filteredClients" :key="client.id" tabindex="0" role="link" :aria-label="`Open ${client.display_name}`" class="group cursor-pointer hover:bg-surface-subtle/50 transition-colors" @click="openClient(client)" @keydown.enter.prevent="openClient(client)" @keydown.space.prevent="openClient(client)"><td class="px-inline-lg py-stack-md"><div class="flex items-center gap-3"><span class="icon-surface icon-surface-accent !h-8 !w-8 !rounded-pill opacity-80" aria-hidden="true"><UserRound class="workspace-icon-sm" /></span><div><div class="type-body-medium text-ink">{{ client.display_name }}</div><div v-if="client.reference" class="type-metadata text-ink-muted">{{ client.reference }}</div></div></div></td><td class="px-inline-lg py-stack-md type-ui text-ink-secondary">{{ appointmentLabel(client.id) }}</td><td v-if="statusFilter==='all'" class="px-inline-lg py-stack-md"><StatusIndicator :tone="client.archived?'neutral':'success'">{{ client.archived?'Archived':'Active' }}</StatusIndicator></td><td class="px-inline-lg py-stack-md text-right"><button v-if="isSampleClient(client)" type="button" class="mr-inline-md inline-flex items-center gap-1.5 type-ui text-ink-muted hover:text-ink disabled:opacity-50" :disabled="archivingSampleId===client.id" @click.stop="toggleSampleArchive(client)"><Archive class="workspace-icon" aria-hidden="true" /><span>{{ archivingSampleId===client.id?'Saving…':client.archived?'Restore sample':'Archive sample' }}</span></button><span class="icon-surface !h-8 !w-8 !rounded-pill border-transparent bg-transparent text-accent group-hover:bg-brand-sage-soft" aria-hidden="true"><ChevronRight class="workspace-icon" /></span></td></tr></tbody></table></div>
    </template>
    <AddClientModal v-if="showAddClient" :submitting="addingClient" :error="addError" @close="showAddClient=false" @submit="handleAddClient" />
  </div>
</template>
<script setup>
import { computed,ref,onMounted } from 'vue';import { useRouter } from 'vue-router';import { Archive,ChevronDown,ChevronRight,ChevronUp,Inbox,Search,Sparkles,UserPlus,UserRound,UsersRound,X } from '@lucide/vue';import { listClients,createClient,listUpcomingClientAppointments,setClientArchived } from '../lib/clients.js';import { createSampleWorkspace,isSampleClient } from '../lib/sampleWorkspace.js';import AddClientModal from '../components/sidebar/AddClientModal.vue';import PageHeader from '../components/ui/PageHeader.vue';import AppButton from '../components/ui/AppButton.vue';import FormControl from '../components/ui/FormControl.vue';import StatusIndicator from '../components/ui/StatusIndicator.vue';
const SAMPLE_GUIDE_STORAGE_KEY='helios.samplePracticeGuide.v1';function initialSampleGuideState(){try{const value=localStorage.getItem(SAMPLE_GUIDE_STORAGE_KEY);return['expanded','collapsed','hidden'].includes(value)?value:'expanded'}catch{return'expanded'}}const router=useRouter(),clients=ref([]),appointments=ref([]),loading=ref(true),error=ref(''),showAddClient=ref(false),addingClient=ref(false),addError=ref(''),seedingSample=ref(false),sampleError=ref(''),sampleActionError=ref(''),archivingSampleId=ref(''),searchQuery=ref(''),statusFilter=ref('active'),sampleGuideState=ref(initialSampleGuideState());
const samplePracticeReady=computed(()=>clients.value.filter(isSampleClient).length>=4),sampleDaniel=computed(()=>clients.value.find(client=>client.reference==='SAMPLE-003')||null),activeCount=computed(()=>clients.value.filter(c=>!c.archived).length),archivedCount=computed(()=>clients.value.filter(c=>c.archived).length),statusOptions=computed(()=>[{value:'active',label:'Active',count:activeCount.value},{value:'archived',label:'Archived',count:archivedCount.value},{value:'all',label:'All',count:clients.value.length}]);const filteredClients=computed(()=>{const q=searchQuery.value.trim().toLowerCase();return clients.value.filter(c=>statusFilter.value==='all'||(statusFilter.value==='archived'?c.archived:!c.archived)).filter(c=>!q||c.display_name?.toLowerCase().includes(q)||c.reference?.toLowerCase().includes(q))});const resultLabel=computed(()=>`${filteredClients.value.length} ${statusFilter.value==='all'?'client':statusFilter.value+' client'}${filteredClients.value.length===1?'':'s'}`),emptyStatusMessage=computed(()=>statusFilter.value==='archived'?'No archived clients.':statusFilter.value==='all'?'No clients yet.':'You don’t have any active clients yet.');const nextAppointments=computed(()=>{const map=new Map();for(const a of appointments.value){if(a.client_id&&!map.has(a.client_id))map.set(a.client_id,a)}return map});function appointmentLabel(id){const a=nextAppointments.value.get(id);if(!a?.starts_at)return'Not scheduled';return new Date(a.starts_at).toLocaleString('en-GB',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}function setSampleGuideState(state){sampleGuideState.value=state;try{localStorage.setItem(SAMPLE_GUIDE_STORAGE_KEY,state)}catch{}}function collapseSampleGuide(){if(sampleGuideState.value==='expanded')setSampleGuideState('collapsed')}function openClient(client){if(isSampleClient(client))collapseSampleGuide();router.push(`/clients/${client.id}`)}
async function loadClients(){loading.value=true;error.value='';try{[clients.value,appointments.value]=await Promise.all([listClients({includeArchived:true}),listUpcomingClientAppointments()])}catch(e){error.value='The clinical directory could not be loaded.'}finally{loading.value=false}}async function ensureExistingSamplePractice(){if(seedingSample.value||clients.value.length<4||!clients.value.every(isSampleClient))return;seedingSample.value=true;sampleError.value='';try{await createSampleWorkspace()}catch(e){sampleError.value=e.message||'The sample practice could not be completed.'}finally{seedingSample.value=false}}async function seedSampleWorkspace(){if(seedingSample.value)return;seedingSample.value=true;sampleError.value='';try{await createSampleWorkspace();setSampleGuideState('expanded');statusFilter.value='active';await loadClients()}catch(e){sampleError.value=e.message||'The sample practice could not be added.'}finally{seedingSample.value=false}}function openSampleDaniel(){if(!sampleDaniel.value)return;collapseSampleGuide();router.push(`/clients/${sampleDaniel.value.id}`)}function openSampleInbox(){collapseSampleGuide();router.push('/transcripts')}async function toggleSampleArchive(client){if(archivingSampleId.value)return;archivingSampleId.value=client.id;sampleActionError.value='';try{const updated=await setClientArchived({clientId:client.id,archived:!client.archived});const i=clients.value.findIndex(c=>c.id===client.id);if(i!==-1)clients.value[i]={...clients.value[i],...updated}}catch(e){sampleActionError.value=e.message||'Could not update the sample client.'}finally{archivingSampleId.value=''}}async function handleAddClient(data){if(addingClient.value)return;addingClient.value=true;addError.value='';try{const c=await createClient(data);clients.value.push(c);clients.value.sort((a,b)=>a.display_name.localeCompare(b.display_name));statusFilter.value='active';showAddClient.value=false}catch(e){addError.value=e.message||'Failed to create client.'}finally{addingClient.value=false}}onMounted(async()=>{await loadClients();await ensureExistingSamplePractice()});
</script>
